package app;import p.Base;import p.Text;public class Main{@SuppressWarnings({"rawtypes","unchecked"})public static void main(String[] args){Text text=new Text("seed");Base raw=text;Base<?> wildcard=(Base<?>)(Object)text;if(args[0].equals("bridge")){raw.write("good");String status="miss";try{raw.write(Integer.valueOf(7));}catch(ClassCastException expected){status="bridge";}System.out.println(status+":"+text.bodies+":"+text.value);Base<Integer> integers=(Base<Integer>)(Object)text;status="miss";try{Integer invalid=integers.read();}catch(ClassCastException expected){status="delayed";}System.out.println(status+":"+text.bodies+":"+text.reads);}else if(args[0].equals("null")){raw.write(null);Base<?> nil=(Base<?>)(Object)null;System.out.println((wildcard.read()==null)+":"+text.bodies+":"+(nil==null));}else{Writer writer=text::write;Reader bound=text::read;ReadFrom unbound=Base<String>::read;writer.write("refs");String first=bound.read();String second=unbound.read(text);System.out.println(first+":"+second+":"+text.bodies+":"+text.reads+":"+(wildcard==text));}}}
